/**
 * @fileoverview Módulo para integrar la IA (orquestador multi-agente) con los comandos del bot de WhatsApp NekoBot.
 * Este módulo define la estructura para disparar la IA con prompts específicos basados en comandos del bot,
 * y propone 3 casos de uso concretos donde la IA puede añadir valor al gameplay de RPG.
 */

// Supongamos que el orquestador multi-agente ya está implementado y accesible.
// En un escenario real, esto sería una importación de otro módulo.
const iaOrchestrator = require('./iaOrchestrator'); // Ruta hipotética

/**
 * @typedef {Object} PromptConfig
 * @property {string} description - Descripción del caso de uso.
 * @property {string} command - El comando del bot que dispara este feature.
 * @property {Function} buildPrompt - Una función que toma los argumentos del comando y construye el prompt para la IA.
 */

/**
 * @type {Array<PromptConfig>}
 * Lista de configuraciones de prompts para integrar la IA con comandos del bot.
 */
const iaCommandIntegrations = [
    {
        description: "Generación de descripciones de escenas detalladas y atmosféricas para el inicio de una nueva aventura o encuentro.",
        command: "/escena",
        buildPrompt: (args, userContext) => {
            // args: array de strings, los argumentos pasados al comando.
            // userContext: objeto con información del usuario (ej: personaje activo, ubicación).
            const theme = args.join(' ') || "un bosque misterioso";
            return `Genera una descripción inmersiva y atmosférica para una escena de RPG de texto. El tema principal es: "${theme}".
            Incluye detalles sensoriales (vista, oído, olfato, tacto), crea un ambiente intrigante y sugiere posibles puntos de interés o peligros.
            El jugador es: ${userContext.activeCharacter?.name || 'un aventurero desconocido'}.
            Contexto adicional: ${userContext.location || 'un lugar desconocido'}.
            Formato: Texto narrativo, sin diálogos directos de NPCs a menos que sea esencial para la atmósfera.`;
        }
    },
    {
        description: "Narración de combates dinámicos, describiendo acciones, reacciones y el estado del combate en tiempo real.",
        command: "/combate",
        buildPrompt: (args, userContext) => {
            // args: [tipo_ataque, objetivo, modificadores]
            // userContext: { activeCharacter, activeCombat }
            const attackType = args[0] || "un ataque básico";
            const target = args[1] || "un enemigo genérico";
            const modifiers = args.slice(2).join(' ');
            const character = userContext.activeCharacter;
            const combatState = userContext.activeCombat; // Podría ser un objeto con HP de ambos, turno, etc.

            if (!character) {
                return "ERROR: No tienes un personaje activo para combatir.";
            }
            if (!combatState) {
                return "ERROR: No hay un combate activo para narrar.";
            }

            return `Narra el siguiente turno de un combate de RPG de texto.
            Personaje del jugador: ${character.name} (HP: ${character.hp}/${character.maxHp}, Stats: ${JSON.stringify(character.stats)}).
            Acción del jugador: ${attackType} contra ${target}. Modificadores: ${modifiers}.
            Estado actual del combate: ${JSON.stringify(combatState)}.
            Describe la acción de forma vívida, incluyendo la respuesta del enemigo y cualquier consecuencia inmediata. Mantén la tensión y el ritmo.
            Formato: Texto narrativo, enfocado en la acción y el impacto.`;
        }
    },
    {
        description: "Creación de NPCs dinámicos con personalidades, motivaciones y diálogos adaptados al contexto de la partida.",
        command: "/npc",
        buildPrompt: (args, userContext) => {
            // args: [rol_npc, descripción_breve, contexto_interaccion]
            const npcRole = args[0] || "un mercader misterioso";
            const briefDescription = args[1] || "parece saber más de lo que dice";
            const interactionContext = args.slice(2).join(' ') || "el jugador busca información sobre una reliquia perdida";
            const character = userContext.activeCharacter;

            return `Crea un NPC (Non-Player Character) para una partida de RPG de texto.
            Rol/Ocupación: ${npcRole}.
            Descripción breve: ${briefDescription}.
            Contexto de la interacción: ${interactionContext}.
            El NPC debe tener una personalidad definida, una motivación clara (aunque no sea obvia al principio) y un estilo de diálogo coherente.
            Genera una breve descripción del NPC y una línea de diálogo inicial que invite a la interacción.
            Considera que el jugador es: ${character?.name || 'un aventurero'}.
            Formato:
            Nombre: [Nombre del NPC]
            Descripción: [Descripción física y de comportamiento]
            Diálogo inicial: "[Línea de diálogo]"`;
        }
    }
];

/**
 * Procesa un comando recibido y, si corresponde, lo integra con la IA.
 * @param {string} command - El comando recibido (ej: "/escena").
 * @param {Array<string>} args - Los argumentos del comando.
 * @param {Object} userContext - Contexto del usuario (ej: personaje activo, grupo).
 * @returns {Promise<string|null>} La respuesta generada por la IA, o null si el comando no se integra con IA.
 */
async function processIaCommand(command, args, userContext) {
    const integration = iaCommandIntegrations.find(
        (integration) => integration.command === command
    );

    if (!integration) {
        return null; // El comando no está integrado con IA
    }

    try {
        const prompt = integration.buildPrompt(args, userContext);
        console.log(`[IA Command Integration] Prompt para "${command}":\n${prompt}`);

        // Aquí se llama al orquestador multi-agente existente.
        // La lógica de fallback y selección de modelos (Gemini/OpenRouter)
        // ya debería estar implementada dentro de iaOrchestrator.
        const iaResponse = await iaOrchestrator.generateResponse(prompt);

        console.log(`[IA Command Integration] Respuesta de IA para "${command}":\n${iaResponse}`);
        return iaResponse;

    } catch (error) {
        console.error(`[IA Command Integration] Error procesando comando IA "${command}":`, error);
        // Devolver un mensaje de error amigable al usuario
        return "Lo siento, ocurrió un error al intentar generar la respuesta de IA. Por favor, intenta de nuevo más tarde.";
    }
}

// Exportar la función principal y la lista de integraciones si se necesita para inspección o configuración dinámica.
module.exports = {
    processIaCommand,
    iaCommandIntegrations
};
```
